namespace Scheduler.Domain.Entities;

/// <summary>
/// Base class for entities that carry an identifier, audit fields and soft deletion
/// (ScheduledTask and Schedule). FR-04, FR-08.
/// </summary>
public abstract class AuditableEntity
{
    /// <summary>Time-ordered UUID generated by the application (BR-01).</summary>
    public Guid Id { get; protected set; } = Guid.CreateVersion7();

    public DateTime CreatedAtUtc { get; protected set; }
    public Guid? CreatedById { get; protected set; }
    public DateTime? UpdatedAtUtc { get; protected set; }
    public Guid? UpdatedById { get; protected set; }

    public bool IsDeleted { get; protected set; }

    /// <summary>
    /// Row version used for optimistic concurrency (PostgreSQL xmin), so two administrators cannot
    /// silently overwrite each other's changes (NFR-17).
    /// </summary>
    public uint Version { get; protected set; }

    protected void MarkCreated(DateTime nowUtc, Guid? userId)
    {
        CreatedAtUtc = nowUtc;
        CreatedById = userId;
    }

    protected void MarkUpdated(DateTime nowUtc, Guid? userId)
    {
        UpdatedAtUtc = nowUtc;
        UpdatedById = userId;
    }
}
